package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import com.google.gson.stream.JsonWriterTestUtil;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertThrows;

public class JsonWriter_value_TriageGen0Test {

    @Test
    public void test_value_NaN() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.NaN));
    }

    @Test
    public void test_value_Infinity() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.POSITIVE_INFINITY));
    }

    @Test
    public void test_value_Finite() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        assertEquals("123.456", out.toString());
    }

    @Test
    public void test_value_Null() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        assertThrows(NullPointerException.class, () -> jsonWriter.value(null));
    }

    @Test
    public void test_value_Nullable() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value((double) null);
        assertEquals("null", out.toString());
    }

    @Test
    public void test_value_Nullable_NaN() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value((double) Double.NaN);
        assertEquals("NaN", out.toString());
    }

    @Test
    public void test_value_Nullable_Infinity() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value((double) Double.POSITIVE_INFINITY);
        assertEquals("Infinity", out.toString());
    }

    @Test
    public void test_value_Nullable_Finite() throws Exception {
        Writer out = new StringWriter();
        JsonWriter jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        assertEquals("123.456", out.toString());
    }
}
